    ["装配后获得【死亡教派】羁绊"] = "Экипируйте, чтобы получить резонанс [Секта Смерти]",
    ["Witch's Curse"] = "Проклятие Демоницы",
    ["Misfortune comes in threes"] = "Несчастье приходит втроем",
    ["Total Damage: Attack × 125% = <img id=\"03\" width=\"40\" height=\"40\"/><HighLight></>{*d,F1690001,atkMin,1.25}, Shield: Max Health × 40% = <img id=\"01\" width=\"40\" height=\"40\"/><HighLight></>{*d,F1690001,maxHp,0.4}"] = "Общий урон: <img id=\"03\" width=\"40\" height=\"40\"/>Атака × <HighLight>125%</> = {*d,F1690001,atkMin,1.25}, щит: <img id=\"01\" width=\"40\" height=\"40\"/>Макс. здоровье × <HighLight>40%</> = {*d,F1690001,maxHp,0.4}",
    ["A total of 25 enemy pieces have been defeated"] = "Всего погибло 25 вражеских фигур",
    ["Player Health is no more than 5."] = "Здоровье игрока — не больше 5",
    ["<HighLight> Deals heavy damage to high-Health enemies </>"] = "<HighLight>Тяжёлый урон по врагам с высоким здоровьем</>",
    ["Drew"] = "Дрю",
    ["我儿子在乡下念书，老师让写作文，题目是“谁是你心中最伟大的国王”。"] = "Мой сын учится в деревне, и учитель попросил его написать эссе на тему «Кто в твоем сердце величайший король?»",
    ["他们看到一个涂着红黄白等各色油彩的小丑跑了过来，不知从哪里变出了一束花，一束塞维亚菊。\n      这束花凑到了梅丽莎和班森眼前，颜色金黄，象征着快乐。\n      梅丽莎和班森略显茫然地望向对面的小丑，只见他满是红黄白等各色油彩的脸上，嘴角高高翘起，固定着一个快乐的笑容，浮夸的笑容，滑稽的笑容。"] = "Они увидели подбежавшего клоуна, чьё лицо было раскрашено в красный, жёлтый и белый цвета. Словно из ниоткуда он достал букет цветов — букет севийских хризантем.\n      Этот букет предстал перед глазами Мелиссы и Бенсона — золотистый, символизирующий счастье.\n      Мелисса и Бенсон слегка растерянно посмотрели на стоявшего перед ними клоуна: на его лице, покрытом красной, жёлтой и белой краской, уголки губ были высоко приподняты, застыв в радостной, преувеличенной, комичной улыбке.",
    ["你好，看上去，这位是您的客人？"] = "Здравствуйте, похоже, этот человек ваш гость?",
    ["Holden"] = "Холден",
}
